Lemma \ref{lem:algo-4} and its proof can be found in Appendix \ref{app:id-formula}, but we provide an overview here for intuition. This lemma requires the same assumptions as Theorem \ref{thm:id-formula}---that $\mb{Z} \cap \mathrm{PossDe}(\mb{X},\g) = \emptyset$ and no proper possibly causal path from $\mb{X}$ to $\mb{Y}$ starts undirected. Under these assumptions, the lemma claims
\begin{align}
    f(\mb{b_i} \,|\, \mb{b_{i-1}}, \dots, \mb{b_0}, do(\mb{x}),\mb{z}) = 
    \begin{cases} 
        f(\mb{b_i} \,|\, \mathrm{pa}(\mb{b_i},\g)) & \mb{Z} \cap \mathrm{PossDe}(\mb{B_i}, \g) = \emptyset\\
        f(\mb{b_i} \,|\, \mb{b_i^N}, \mb{z}) & \mb{Z} \cap \mathrm{PossDe}(\mb{B_i}, \g) \neq \emptyset.
    \end{cases} \label{lem:algo-4-claim}
\end{align}
The proof of this lemma relies on applying Rules 1-3 of \citeauthor{pearl2009causality}'s (\citeyear{pearl2009causality}) do calculus (Theorem \ref{thm:do-calc}, App. \ref{app:existing}) to an arbitrary DAG $\g[D] \in [\g]$. To show the top equality of \eqref{lem:algo-4-claim} holds, we use Rules 1 and 3 to restrict the conditioning set---including variables in the do intervention---to variables also in $\mathrm{Pa}(\mb{B_i},\g)$. Applying Rule 2 leaves a conditioning set of $\big(\cup_{j=0}^{i-1} \mb{B_j} \cup \mb{Z} \cup \mb{X} \big) \cap \mathrm{Pa}(\mb{B_i}, \g)$, which is simply $\mathrm{Pa}(\mb{B_i},\g)$. To show that the d-separations for these three rules hold, we assume, for sake of contradiction, that under a specific conditioning set, there is an open path in $\g[D]$ between $\mb{B_i}$ and variables in $\big(\cup_{j=1}^{i-1} \mb{B_j} \cup \mb{Z} \big) \setminus \mathrm{Pa}(\mb{B_i}, \g)$ and $\mb{X}$. Informally, we rely on the fact that $\g$ cannot contain a possibly causal path from $\mb{B_i}$ to these variables. We use similar logic to show the lower equality of \eqref{lem:algo-4-claim} holds, by applying Rules 1 and 3 to reduce the conditioning set to $\mb{B_i^N} \cup \mb{Z}$.

\begin{align}
        f(\mb{b_i} \,|\, \mb{b_{i-1}}, \dots, \mb{b_0}, do(\mb{x}),\mb{z}) = 
        \begin{cases} 
            f(\mb{b_i} \,|\, \mathrm{pa}(\mb{b_i},\g)) & \mb{Z} \cap \mathrm{PossDe}(\mb{B_i}, \g) = \emptyset\\
            f(\mb{b_i} \,|\, \mb{b_i^N}, \mb{z}) & \mb{Z} \cap \mathrm{PossDe}(\mb{B_i}, \g) \neq \emptyset.
        \end{cases} \label{lem:algo-4-claim}
    \end{align}

\begin{align}
    f(\mb{y} \,|\, do(\mb{x})) = \int \prod_{i=1}^k f(\mb{b_i} \,|\, \mathrm{pa}(\mb{b_i},\g)) \mathop{}\!\mathrm{d} \mb{b}. \label{eq:id-formula-unconditional}
\end{align}

\label{thm:id-rule3}
    Let $\mb{X}$, $\mb{Y}$, and $\mb{Z}$ be pairwise disjoint node sets in a causal MPDAG $\g$, where $\mb{Z} \cap \mathrm{PossDe}(\mb{X},\g) = \emptyset$ and $\mb{Y} \cap \mathrm{PossDe}(\mb{X},\g) = \emptyset$. Then for any $f$ consistent with $\g$,
    \begin{align}
        f(\mb{y} \,|\, do(\mb{x}),\mb{z}) = f(\mb{y} \,|\, \mb{z}). \label{eq:id-formula-rule3}
    \end{align}

\begin{align}
        f(\mb{y} \,|\, do(\mb{x}),\mb{z}) = f(\mb{y} \,|\, \mb{z}). \label{eq:id-formula-rule3}
    \end{align}

\label{ex:id-cas}
    Let $\g$ be the causal MPDAG in Figure \ref{fig:ex1}\subref{fig:ex-id-cas}, and let $\mb{X} = \{X\}$, $\mb{Y}=\{Y\}$, and $\mb{Z}=\{V_1\}$. To use Theorem \ref{thm:id-formula}, we confirm $\mb{Z} \cap \mathrm{PossDe}(\mb{X}, \g) = \emptyset$ and no possibly causal path from $\mb{X}$ to $\mb{Y}$ starts undirected. Then we find $\mb{B_1}=\{V_2\}$ (where $1 \in \mb{I_N}$), $\mb{B_2}=\{Y\}$ (where $2 \in \mb{I_E}$), and $\mb{B}= \{V_2\}$. Thus for $f$ consistent with $\g$,
    \vskip -.6cm
    \begin{align*}
        f(\mb{y} \,|\, do(\mb{x}),\mb{z})
            &=\scaleobj{.6}{\int} \,f\big(\mb{b_2} \,|\, \mathrm{pa}(\mb{b_2},\g)\big)\, f(\mb{b_1} \,|\, \mb{b_1^N},\mb{z}) \mathop{}\!\mathrm{d} \mb{b} \\
            &=\scaleobj{.6}{\int} \,f(y \,|\, x, v_1, v_2) \,f(v_2 \,|\, v_1) \mathop{}\!\mathrm{d} v_2.
    \end{align*}
    Compare this to Example 2 of \cite{laplante2024conditional}, where the authors find the identical form of $f(\mb{y}|do(\mb{x}),\mb{z})$ by showing that $\mb{S} := \{V_2\}$ is a conditional adjustment set.

\begin{align*}
        f(\mb{y} \,|\, do(\mb{x}),\mb{z})
            &=\scaleobj{.6}{\int} \,f\big(\mb{b_2} \,|\, \mathrm{pa}(\mb{b_2},\g)\big)\, f(\mb{b_1} \,|\, \mb{b_1^N},\mb{z}) \mathop{}\!\mathrm{d} \mb{b} \\
            &=\scaleobj{.6}{\int} \,f(y \,|\, x, v_1, v_2) \,f(v_2 \,|\, v_1) \mathop{}\!\mathrm{d} v_2.
    \end{align*}

\label{ex:id-nocas}
    Let $\g$ be the causal DAG (and therefore, MPDAG) in Figure \ref{fig:ex1}\subref{fig:ex-id-nocas}, and let $\mb{X} = \{X_1, X_2\}$, $\mb{Y}=\{Y\}$, and $\mb{Z}=\{V_2\}$. To use Theorem \ref{thm:id-formula}, we confirm $\mb{Z} \cap \mathrm{PossDe}(\mb{X}, \g) = \emptyset$ and no possibly causal path from $\mb{X}$ to $\mb{Y}$ starts undirected. Then we find $\mb{B_1}=\{V_1\}$, $\mb{B_2}=\{Y\}$ (where $1,2 \in \mb{I_E}$), and $\mb{B}= \{V_1\}$. Thus for $f$ consistent with $\g$,
    \vskip -.6cm
    \begin{align}
        f(\mb{y} \,|\, do(\mb{x}),\mb{z})
            &=\scaleobj{.6}{\int} \,f\big(\mb{b_1} \,|\, \mathrm{pa}(\mb{b_1},\g)\big) \,f\big(\mb{b_2} \,|\, \mathrm{pa}(\mb{b_2},\g)\big) \mathop{}\!\mathrm{d} \mb{b} \nonumber\\
            &=\scaleobj{.6}{\int} \,f(v_1 \,|\, x_1) \,f(y \,|\, x_2, v_1, v_2) \mathop{}\!\mathrm{d} v_1. \nonumber
    \end{align}
    Note that \cite{laplante2024conditional} show there is no conditional adjustment set in this case (see their Figure 4).

\begin{align}
        f(\mb{y} \,|\, do(\mb{x}),\mb{z})
            &=\scaleobj{.6}{\int} \,f\big(\mb{b_1} \,|\, \mathrm{pa}(\mb{b_1},\g)\big) \,f\big(\mb{b_2} \,|\, \mathrm{pa}(\mb{b_2},\g)\big) \mathop{}\!\mathrm{d} \mb{b} \nonumber\\
            &=\scaleobj{.6}{\int} \,f(v_1 \,|\, x_1) \,f(y \,|\, x_2, v_1, v_2) \mathop{}\!\mathrm{d} v_1. \nonumber
    \end{align}

\label{ex:id-rule3}
    Let $\g$ be the causal MPDAG in Figure \ref{fig:ex1}\subref{fig:ex-id-rule3}, and let $\mb{X} = \{X\}$, $\mb{Y}=\{Y\}$, and $\mb{Z}=\{Z\}$. To use Theorem \ref{thm:id-rule3}, we confirm $\mb{Y} \cap \mathrm{PossDe}(\mb{X}, \g) = \emptyset$ and $\mb{Z} \cap \mathrm{PossDe}(\mb{X}, \g) = \emptyset$. Thus for $f$ consistent with $\g$,
    \begin{align*}
        f(\mb{y} \,|\, do(\mb{x}),\mb{z})
            &= f(y \,|\, z).
    \end{align*}

\begin{align*}
        f(\mb{y} \,|\, do(\mb{x}),\mb{z})
            &= f(y \,|\, z).
    \end{align*}

\label{thm:do-calc-mpdag} 
    Let $\mb{X}$, $\mb{Y}$, $\mb{Z}$, and $\mb{W}$ be pairwise disjoint node sets in a causal MPDAG $\g=(\mb{V,E})$. Let $\g_{\overline{\mb{X}}\underline{\mb{Z}}}$ denote the graph obtained by deleting all edges into $\mb{X}$ and all edges out of $\mb{Z}$ from $\g$. We write $\g_{\overline{\mb{X}}\underline{\mb{Z}}}$ as $\g_{\underline{\mb{Z}}}$ when $\mb{X}$ is empty and as $\g_{\overline{\mb{X}}}$ when $\mb{Z}$ is empty. Then the following hold for all densities $f$ consistent with $\g$.
    \vskip .075in

    \textbf{Rule~1.} If $(\mb{Y} \perp_{d} \mb{Z} | \mb{X}, \mb{W})_{\g_{\overline{\mb{X}}}}$, then
    \begin{align}
        f(\mb{y} | do(\mb{x}), \mb{z}, \mb{w}) = f(\mb{y} | do(\mb{x}), \mb{w}). \label{eq:rule1-do-mpdag}
    \end{align}

    \textbf{Rule~2.} If $(\mb{Y} \perp_{d} \mb{Z} | \mb{X}, \mb{W})_{\g_{\overline{\mb{X}}\underline{\mb{Z}}}}$, then
    \begin{align} \label{eq:rule2-do-mpdag}
        f(\mb{y} | do(\mb{z}), \mb{w}, do(\mb{x})) = f(\mb{y} | \mb{z}, \mb{w}, do(\mb{x})).
    \end{align}

    \textbf{Rule~3.} If $(\mb{Y} \perp_{d} \mb{Z} | \mb{X}, \mb{W})_{\g_{\overline{\mb{X}}, \overline{\mb{Z'(W)}}}}$, then
    \begin{align}
    \label{eq:rule3-do-mpdag}
        \begin{split}
            f(\mb{y} | do(\mb{z}), \mb{w}, do(\mb{x})) = f(\mb{y} | \mb{w}, do(\mb{x})),
        \end{split}
    \end{align}
    \hskip .86in where $\mb{Z'(W)} := \mb{Z} \setminus \mathrm{PossAn}(\mb{W}, \g_{\mb{V} \setminus \mb{X}})$.

\begin{align}
        f(\mb{y} | do(\mb{x}), \mb{z}, \mb{w}) = f(\mb{y} | do(\mb{x}), \mb{w}). \label{eq:rule1-do-mpdag}
    \end{align}

\begin{align} \label{eq:rule2-do-mpdag}
        f(\mb{y} | do(\mb{z}), \mb{w}, do(\mb{x})) = f(\mb{y} | \mb{z}, \mb{w}, do(\mb{x})).
    \end{align}

\begin{align}
    \label{eq:rule3-do-mpdag}
        \begin{split}
            f(\mb{y} | do(\mb{z}), \mb{w}, do(\mb{x})) = f(\mb{y} | \mb{w}, do(\mb{x})),
        \end{split}
    \end{align}

\label{ex:do-multi}
    Reconsider Example \ref{ex:id-cas}, where we found the form of a conditional effect using our identification formula. We could instead use Theorem \ref{thm:do-calc-mpdag}:
    \begin{align*}
        f(\mb{y}|do(\mb{x}),\mb{z})
            &=\scaleobj{.6}{\int} \,f(y, v_2|do(x), v_1) \mathop{}\!\mathrm{d} v_2 \\
            &=\scaleobj{.6}{\int} \,f(y|do(x), v_1, v_2) \,f(v_2|do(x), v_1) \mathop{}\!\mathrm{d} v_2 \\
            &=\scaleobj{.6}{\int} \,f(y|x, v_1, v_2) \,f(v_2|v_1) \mathop{}\!\mathrm{d} v_2,
    \end{align*}
    The first two equalities hold by the law of total probability and the chain rule, respectively. The third holds by Rules 2 and 3, since $Y \perp_{d} X \,|\, V_1,V_2$ in $\g_{\underline{\mb{X}}}$ and $V_2 \perp_{d} X \,|\, V_1$ in $\g_{\overline{\mb{X}}}$. This example provides a case where all three methods---conditional adjustment, the identification formula, and the do calculus for MPDAGs---find the same form for the conditional effect.

\begin{align*}
        f(\mb{y}|do(\mb{x}),\mb{z})
            &=\scaleobj{.6}{\int} \,f(y, v_2|do(x), v_1) \mathop{}\!\mathrm{d} v_2 \\
            &=\scaleobj{.6}{\int} \,f(y|do(x), v_1, v_2) \,f(v_2|do(x), v_1) \mathop{}\!\mathrm{d} v_2 \\
            &=\scaleobj{.6}{\int} \,f(y|x, v_1, v_2) \,f(v_2|v_1) \mathop{}\!\mathrm{d} v_2,
    \end{align*}

\label{ex:do-rule2}
    Let $\g$ be the causal MPDAG in Figure \ref{fig:ex-rules1+2}, and suppose we want to identify the causal effect of $X$ on $Y$ given $\{V_1,V_2\}$. Note that we cannot use Theorem \ref{thm:id-formula}, since $\{V_1,V_2\} \cap \mathrm{PossDe}(X, \g) \neq \emptyset$. However, we can use Theorem \ref{thm:do-calc-mpdag} to show
    \begin{align*}
        f(y \,|\, do(x), v_1, v_2)
            &= f(y \,|\, x, v_1, v_2).
    \end{align*}
    The equality follows from Rule 2, since $Y \perp_{d} X \,|\, V_1, V_2$ in $\g_{\underline{\mb{X}}}$.

\begin{align*}
        f(y \,|\, do(x), v_1, v_2)
            &= f(y \,|\, x, v_1, v_2).
    \end{align*}

\label{ex:do-rule3}
    Let $\g$ be a causal MPDAG containing only $X - Z \to Y$, and suppose we want to identify the causal effect of $X$ on $Y$ given $Z$. Note that we cannot use Theorems \ref{thm:id-formula} or \ref{thm:id-rule3}, since $Z \in \mathrm{PossDe}(X, \g)$. However, we can use Theorem \ref{thm:do-calc-mpdag} to show
    \begin{align*}
        f(y \,|\, do(x), z)
            &= f(y \,|\, z).
    \end{align*}    
    This holds by Rule 3, since $Y \perp_{d} X \,|\, Z$ in $\g_{\overline{\mb{X}}}$.

\begin{align*}
        f(y \,|\, do(x), z)
            &= f(y \,|\, z).
    \end{align*}

    \vspace{.3cm}
    \Input{Disjoint node sets $\mb{X}, \mb{Y}, \mb{Z} \subseteq \mb{V}$ and causal MPDAG $\g=(\mb{V,E})$}
    \Output{Expression for $f(\mb{y} \,|\, do(\mb{x}), \mb{z})$, for any $f$ consistent with $\g$, or FAIL}
    \vspace{.3cm}
    \SetAlgoVlined
    Let $\mb{Z'} =  \mb{Z}$ and $\mb{X'} = \mb{X}$;\\ \vskip .2cm
    \While{
    $\exists$ a proper possibly causal path $\mb{X'}$ to $\mb{Y} \cup \mb{Z'}$ in $\g$ that starts undirected \label{alg:cidm-a}}{
        Pick $X \in \mb{X'}$ on such a path;\\
        \uIf{
        $(\, \mb{Y} \perp_{d} X \,\,|\,\, \mb{X'} \setminus \{X\}, \mb{Z'} \,)_{\, \g_{\overline{\mb{X'} \setminus \{X\}} \underline{X}}}$}{
            Add $X$ to $\mb{Z'}$;
                \hspace*{20em}
                \rlap{\smash{$\left.\begin{array}{@{}c@{}}\\{}\\{}\\{}\end{array}\right\}
                \begin{tabular}{c}Applies Rule 2 of\\Theorem \ref{thm:do-calc-mpdag}\end{tabular}$}}\\
            Remove $X$ from $\mb{X'}$;
        }\Else{
        \Return FAIL\; \label{alg:cidm-b}
        }
    }\vskip .2cm
    \uIf{$(\, \mb{Y} \perp_{d} \mb{X'} \,\,|\,\, \mb{Z'} \,)_{\, \g_{\overline{\mb{X'}(\mb{Z'})}}}$ where $\mb{X'}(\mb{Z'}) := \mb{X'} \setminus \mathrm{PossAn}(\mb{Z'},\g)$ \label{alg:cidm-c}}{
        \Return $f(\mb{y} \,|\, \mb{z'})$;\label{alg:cidm-d}
            \hspace*{19.85em}
            \rlap{\smash{$\left.\begin{array}{@{}c@{}}\\{}\\{}\end{array}\right\}
            \begin{tabular}{c}Applies Rule 3 of\\Theorem \ref{thm:do-calc-mpdag}\end{tabular}$}}
        \vskip .15cm
    }\Else{
        Let $\mb{Z^D} = \mb{Z'} \cap \mathrm{PossDe}(\mb{X'}, \g)$;\label{alg:cidm-e}\\
        Let $\mb{Z^N} = \mb{Z'} \setminus \mathrm{PossDe}(\mb{X'}, \g)$;\label{alg:cidm-f}\\
        Let $A =$ identification formula for $f(\mb{y},\mb{z^{\scriptscriptstyle{D}}} \,|\, do(\mb{x'}), \mb{z^{\scriptscriptstyle{N}}})$;\label{alg:cidm-g}
            \hspace*{3.6em}
            \rlap{\smash{$\left.\begin{array}{@{}c@{}}\\{}\\{}\\{}\\{}\\{}\end{array}\right\}
            \begin{tabular}{c}Applies \\Theorem \ref{thm:id-formula}\end{tabular}$}}\\
        Let $B =$ identification formula for $f(\mb{z^{\scriptscriptstyle{D}}} \,|\, do(\mb{x'}), \mb{z^{\scriptscriptstyle{N}}})$;\label{alg:cidm-h}\\
        \Return $\frac{A}{B}$;\label{alg:cidm-i}
    }
\caption{Conditional Identification for MPDAGs (\texttt{CIDM})}
\label{alg:cidm}

\begin{align}
    f(\mb{y} \,|\, do(\mb{x'}), \mb{z'}) &= \frac{f(\mb{y}, \mb{z^{\scriptscriptstyle{D}}} \,|\, do(\mb{x'}), \mb{z^{\scriptscriptstyle{N}}} )} {f(\mb{z^{\scriptscriptstyle{D}}} \,|\, do(\mb{x'}), \mb{z^{\scriptscriptstyle{N}}} )}. \label{eq:alg-frac}
\end{align}

\label{ex:alg-pass1}
    Let $\g$ be the causal MPDAG in Figure \ref{fig:ex-alg}\subref{fig:ex-alg-a}, and let $\mb{X} = \{X_1,X_2\}$, $\mb{Y} = \{Y\}$, and $\mb{Z} = \{Z\}$. To use Algorithm \ref{alg:cidm}, we first consider the \emph{\texttt{while}} loop of lines \ref{alg:cidm-a}-\ref{alg:cidm-b}. Since there is a possibly causal path from $X_1 \in \mb{X}$ to $\mb{Y} \cup \mb{Z}$ that starts undirected and does not contain $X_2$, we confirm that $\mb{Y} \perp_{d} X_1 \,|\, X_2, \mb{Z}$ in $\g_{\overline{X_2}\underline{X_1}}$. Thus, we define $\mb{X'} = \{X_2\}$ and $\mb{Z'} = \{X_1,Z\}$. Now that all possibly causal paths from $\mb{X'}$ to $\mb{Y} \cup \mb{Z'}$ start directed, we exit the \emph{\texttt{while}} loop. Then we skip lines \ref{alg:cidm-c}-\ref{alg:cidm-d} since $\mb{Y} \not\perp_{d} \mb{X'} \,|\, \mb{Z'}$ in $\g_{\overline{\mb{X'}}}$. Finally, by lines \ref{alg:cidm-e}-\ref{alg:cidm-i},
    \begin{align*}
