                               & \mathrm{Cov}_{f_*}(Z_1,Z_2) & \ddots & & &	& \\
       	\makebox(0,0){\text{\huge0}}               &                        & \ddots & & \mathrm{Cov}_{f_*}(Z_{m-1}, Z_m) 	& & \\
                               & & & & 1                     & \mathrm{Cov}_{f_*}(Z_m, Y) \\
                               & & & & \mathrm{Cov}_{f_*}(Z_m, Y) & 1 \\
    \end{block}
    \end{blockarray}.\\
    \Sigma_{m+1,1} &= \frac{(-1)^{m+2}}{\mathrm{Det}(\mb{\Sigma})} \mathrm{Cov}_{f_*}(Z_0,Z_1) \cdots \mathrm{Cov}_{f_*}(Z_{m-1},Z_m) \\
    &\neq 0.
    \end{align*}
    The final equality follows from Lemma \ref{lem:sem-covariance}, since for each $i \in \{0, \dots, m-1\}$, $\g[D]^{1'}_{\overline{\mb{X}}}$ contains a node in $\{P_2, \dots, P_k\}$ with causal paths to $Z_i$ and $Z_{i+1}$.
\hfill \rule{1.5ex}{1.5ex}
\end{itemize}

