For ease of notation, let $Z_0=R_n$ and let $Z_i = Q_{i_{k_i}}$ for all $i \in \{1, \dots, m\}$.
    \begin{align*}
        \mathbb{E}_{f_2}[Y \,|\, do(&\mb{X}=\mb{1}), \mb{Z} = \mb{0}]\\[.1cm]
            &\,=\, \left. \mathbb{E}_{f_2}[Y \,|\, Z_0, \dots, Z_m] \,\, \right\rvert_{\, \{Z_0, \dots, Z_m\}=\mb{0}}\\[-.4cm]
            &\,=\, \left. \begin{bmatrix}
                                \mathrm{Cov}_{f_2}(Y, Z_0) \,\, \cdots \,\, \mathrm{Cov}_{f_2}(Y, Z_m) 
                          \end{bmatrix} 
                          \, \mb{\Sigma}^{-1}
                          \begin{bmatrix}
                                Z_0 \\ \vdots \\ Z_m
                          \end{bmatrix} 
                          \,\, \right\rvert_{\, \{Z_0, \dots, Z_m\}=\mb{0}}\\[-.5cm]
            &\,=\, 0,
    \end{align*}
    where $\mb{\Sigma}$ is the covariance matrix of $\{Z_0, \dots, Z_m\}^T$ under $f_2$ (and where $\mb{\Sigma}$ is invertible since $\mb{V}$ is non-degenerate).

\begin{align*}
        \mathbb{E}_{f_2}[Y \,|\, do(&\mb{X}=\mb{1}), \mb{Z} = \mb{0}]\\[.1cm]
            &\,=\, \left. \mathbb{E}_{f_2}[Y \,|\, Z_0, \dots, Z_m] \,\, \right\rvert_{\, \{Z_0, \dots, Z_m\}=\mb{0}}\\[-.4cm]
            &\,=\, \left. \begin{bmatrix}
                                \mathrm{Cov}_{f_2}(Y, Z_0) \,\, \cdots \,\, \mathrm{Cov}_{f_2}(Y, Z_m) 
                          \end{bmatrix} 
                          \, \mb{\Sigma}^{-1}
                          \begin{bmatrix}
                                Z_0 \\ \vdots \\ Z_m
                          \end{bmatrix} 
                          \,\, \right\rvert_{\, \{Z_0, \dots, Z_m\}=\mb{0}}\\[-.5cm]
            &\,=\, 0,
    \end{align*}

\begin{align*}
        \mb{\Sigma} \,=\, &
        \begin{blockarray}{cccccc}
        \begin{block}{[cccccc]}
            1   			       & \mathrm{Cov}_{f_*}(Z_0,Z_1) & & & & \\
      	    \mathrm{Cov}_{f_*}(Z_0,Z_1) & 1                      & \ddots & & & \makebox(0,0){\text{\huge0}} \\
                                   & \mathrm{Cov}_{f_*}(Z_1,Z_2) & \ddots & & &	& \\
           	\makebox(0,0){\text{\huge0}}               &                        & \ddots & & \mathrm{Cov}_{f_*}(Z_{m-1}, Z_m) 	& & \\
                                   & & & & 1                     & \mathrm{Cov}_{f_*}(Z_m, Y) \\
                                   & & & & \mathrm{Cov}_{f_*}(Z_m, Y) & 1 \\
        \end{block}
        \end{blockarray}.\\
        \Sigma_{m+1,1} &= \frac{(-1)^{m+2}}{\mathrm{Det}(\mb{\Sigma})} \mathrm{Cov}_{f_*}(Z_0,Z_1) \cdots \mathrm{Cov}_{f_*}(Z_{m-1},Z_m) \\
        &\neq 0.
        \end{align*}

\label{lem:helper-for-annoying-case}
    Let $p = \langle V_1, \dots, V_k \rangle, k> 1$, be a definite status path in $\g = (\mb{V, E})$, where $\g$ is either a causal MPDAG or there exists a causal MPDAG $\g^{'}$ and node sets $\mb{A} \subseteq \mb{V}$, and $\mb{B} \subseteq \mb{V} \setminus \mb{A}$ such that $\g \equiv \g^{'}_{\overline{A} \underline{B}}$. Further, let $\mb{C} \subseteq \mb{V}$.

    Suppose $p$ is d-connecting given $\mb{C}$ in $\g$ and suppose $\g$ contains an edge $\langle V_i, V_j \rangle$, $1 \le i < j \le k$, such that $t = p(V_1, \dots, V_i) \oplus \langle V_i, V_j \rangle \oplus p(V_j, V_k)$ is also a definite status path in $\g$. If $V_i$ and $V_j$ are definite non-colliders or endpoints on $p$, then $t$ is also d-connecting given $\mb{C}$.

\label{lem:unishielded-colliders}
    Let $\mb{X,Y,Z}$ be pairwise disjoint node sets in a causal MPDAG $\g = (\mb{V,E})$. Suppose there is no possibly causal path in $\g$ from $X$ to $\mb{Y}$ that starts undirected and does not contain $\mb{X} \setminus \{X\} \cup \mb{Z}$. Further, suppose there is a possibly causal path in $\g$ from $X$ to $\mb{Z}$ that starts undirected and does not contain $\mb{X} \setminus \{X\} \cup \mb{Y}$, where $(X \not \perp_{d} \mb{Y} | \mb{X} \setminus \{X\}, \mb{Z})_{\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}}$. Then consider the following sets.
    \begin{align*}
        \mb{S_1} &= \left\{\begin{array}{ll}
                                \text{definite status paths in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$ from $X$ to $\mb{Y}$ that are} \\
                                \text{d-connecting given $\mb{X} \setminus \{X\} \cup \mb{Z}$}
                           \end{array}\right\}.\\
        \mb{S_2} &= \{ \text{paths in $\mb{S_1}$ with the fewest colliders} \}.\\[.4cm]
        \mb{S_3} &= \{ \text{paths in } \mb{S_2} \text{ that start undirected}\}.\\
        \mb{S_4} &= \{ \text{paths in $\mb{S_3}$ with the fewest edges} \}.\\
        \mb{S_5} &= \{ \text{paths in $\mb{S_4}$ with a shortest distance to $\mb{Z}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$} \}.\\[.4cm]
        \mb{S_6} &= \{ \text{paths in $\mb{S_2}$ with the fewest edges} \}.\\
        \mb{S_7} &= \{ \text{paths in $\mb{S_6}$ with a shortest distance to $\mb{Z}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$} \}.
    \end{align*}
    When $\mb{S_3} \neq \emptyset$, pick an arbitrary path in $\mb{S_5}$. When $\mb{S_3} = \emptyset$, pick an arbitrary path in $\mb{S_7}$. Call this path $p := \langle X = P_1, \dots, P_k = Y \rangle$, $k > 1$, $Y \in \mb{Y}$, and let $p^*$ be the path in $\g$ corresponding to $p$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$. Then the following hold.
    \begin{enumerate}[label = (\roman*)]
        \item\label{unishielded-coll-case0} $p$ contains no nodes in $\mb{X} \setminus \{X\}$ or $\mb{Y} \setminus \{Y\}$.
        \item \label{unishielded-coll-case1} $\g$ does not contain $X - P_i$ for any $i > 2$.
        \item \label{unishielded-coll-case2} Every collider on $p$ or $p^*$ is unshielded in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$ or $\g$, respectively. 
    \end{enumerate}

\begin{align*}
        \mb{S_1} &= \left\{\begin{array}{ll}
                                \text{definite status paths in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$ from $X$ to $\mb{Y}$ that are} \\
                                \text{d-connecting given $\mb{X} \setminus \{X\} \cup \mb{Z}$}
                           \end{array}\right\}.\\
        \mb{S_2} &= \{ \text{paths in $\mb{S_1}$ with the fewest colliders} \}.\\[.4cm]
        \mb{S_3} &= \{ \text{paths in } \mb{S_2} \text{ that start undirected}\}.\\
        \mb{S_4} &= \{ \text{paths in $\mb{S_3}$ with the fewest edges} \}.\\
        \mb{S_5} &= \{ \text{paths in $\mb{S_4}$ with a shortest distance to $\mb{Z}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$} \}.\\[.4cm]
        \mb{S_6} &= \{ \text{paths in $\mb{S_2}$ with the fewest edges} \}.\\
        \mb{S_7} &= \{ \text{paths in $\mb{S_6}$ with a shortest distance to $\mb{Z}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$} \}.
    \end{align*}

\label{lem:collider-paths}
    Let $\mb{X,Y,Z}$ be pairwise disjoint node sets in a causal MPDAG $\g = (\mb{V,E})$. Suppose there is no possibly causal path in $\g$ from $X$ to $\mb{Y}$ that starts undirected and does not contain $\mb{X} \setminus \{X\} \cup \mb{Z}$. Further, suppose there is a possibly causal path in $\g$ from $X$ to $\mb{Z}$ that starts undirected and does not contain $\mb{X} \setminus \{X\} \cup \mb{Y}$, where $(X \not \perp_{d} \mb{Y} | \mb{X} \setminus \{X\}, \mb{Z})_{\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}}$. Then consider the following sets.
    \begin{align*}
