                           \end{array}\right\}.\\
        \mb{S_2} &= \{ \text{paths in $\mb{S_1}$ with the fewest colliders} \}.\\[.4cm]
        \mb{S_3} &= \{ \text{paths in } \mb{S_2} \text{ that start undirected}\}.\\
        \mb{S_4} &= \{ \text{paths in $\mb{S_3}$ with the fewest edges} \}.\\
        \mb{S_5} &= \{ \text{paths in $\mb{S_4}$ with a shortest distance to $\mb{Z}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$} \}.\\[.4cm]
        \mb{S_6} &= \{ \text{paths in $\mb{S_2}$ with the fewest edges} \}.\\
        \mb{S_7} &= \{ \text{paths in $\mb{S_6}$ with a shortest distance to $\mb{Z}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$} \}.
    \end{align*}
    When $\mb{S_3} \neq \emptyset$, pick an arbitrary path in $\mb{S_5}$. When $\mb{S_3} = \emptyset$, pick an arbitrary path in $\mb{S_7}$. Call this path $p := \langle X = P_1, \dots, P_k = Y \rangle$, $k > 1$, $Y \in \mb{Y}$. Let $\mb{C} = \{C_1, \dots, C_m \}$, $1 \le m \le k-3$, be the set of all colliders on $p$ in order of their appearance on $p$, and let $q_i = \langle C_i = Q_{i_1}, \dots, Q_{i_{k_i}} \rangle$ be a shortest causal path from $C_i$ to $\mb{Z}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$. Further, let $\g[C]$ be the CPDAG that respresents all the DAGs in $[\g]$, and let $p^*$ and $q_i^*$, $i \in \{1, \dots, m \}$, be the paths in $\g[C]$ corresponding to $p$ and $q_i$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$.

    \vskip .1in
    \noindent
    Then if $\mb{C} \neq \emptyset$, the following hold.
    \begin{enumerate}[label = (\roman*)]
        \item\label{q-prop1}
        Each $q_i^*$ is causal.

        \item\label{q-prop2}
        $C_i$ is the only node on both $p$ and $q_i$.

        \item\label{q-prop3}
        $q_i$ and $q_j$ do not share any nodes, where $i \neq j$.
    \end{enumerate}

\begin{align*}
        \mb{S_1} &= \left\{\begin{array}{ll}
                                \text{definite status paths in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$ from $X$ to $\mb{Y}$ that are} \\
                                \text{d-connecting given $\mb{X} \setminus \{X\} \cup \mb{Z}$}
                           \end{array}\right\}.\\
        \mb{S_2} &= \{ \text{paths in $\mb{S_1}$ with the fewest colliders} \}.\\[.4cm]
        \mb{S_3} &= \{ \text{paths in } \mb{S_2} \text{ that start undirected}\}.\\
        \mb{S_4} &= \{ \text{paths in $\mb{S_3}$ with the fewest edges} \}.\\
        \mb{S_5} &= \{ \text{paths in $\mb{S_4}$ with a shortest distance to $\mb{Z}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$} \}.\\[.4cm]
        \mb{S_6} &= \{ \text{paths in $\mb{S_2}$ with the fewest edges} \}.\\
        \mb{S_7} &= \{ \text{paths in $\mb{S_6}$ with a shortest distance to $\mb{Z}$ in $\g_{\overline{\mb{X} \setminus \{X\}} \underline{X}}$} \}.
