    \end{enumerate}

    \item[\ref{q-prop3}]
    Lastly, we show that $q_i$ and $q_j$ such that $i, j \in \{1, \dots, m\}$, $i<j$ cannot contain a node in common by contradiction. Hence, let $Q_{i_d}$, $d >1$, be the closest node to $Q_{i_1}$ on $q_i$ that is also on $q_j$. Then the path $p(X,C_i) \oplus q_i(C_i, Q_{i_d}) \oplus (-q_j(Q_{i_d}, C_j)) \oplus p(C_j, Y)$ contradicts the choice of $p$ as it contains one fewer collider than $p$. \hfill \rule{1.5ex}{1.5ex}
